class Solution {
public:
    long long countSubarrays(vector<int>& nums, int minK, int maxK) {
        long long ans = 0;
        int left = -1, minPos = -1, maxPos = -1;
        for (int r = 0; r < (int)nums.size(); r++) {
            if (nums[r] < minK || nums[r] > maxK) {
                left = r;
            }
            if (nums[r] == minK) minPos = r;
            if (nums[r] == maxK) maxPos = r;
            int start = min(minPos, maxPos);
            if (start > left) {
                ans += start - left;
            }
        }
        return ans;
    }
};
